@startuml

enum LevelOfTutoring {
  PrimarySchool
  HighSchool
  University
}

enum PaymentKind {
  CreditCard
  WireTransfer
}

class User {
  + name : string
  + email : string
}

class Student extends User {}

class Tutor extends User {
  + bankAccount : string
}

class TutoringOffer {
  + subject : string
  + expertiseLevel : LevelOfTutoring
  + hourlyPrice : float
}

class TutorAvailability {
  + dayOfWeek : string
  + startTime : time
  + endTime : time
}

class TutoringRequest {
  + targetDate : date
  + targetTime : time
  + requestedLevel : LevelOfTutoring
}

class TutoringSession {
  + sessionDate : date
  + sessionTime : time
  + status : string
}

class Payment {
  + amount : float
  + kind : PaymentKind
}

Tutor "1" -- "*" TutoringOffer
Tutor "1" -- "*" TutorAvailability
Tutor "1" -- "*" TutoringOffer : offers
Tutor "1" -- "*" TutoringRequest : receives
Student "1" -- "*" TutoringRequest : makes
TutoringRequest "1" -- "0..1" TutoringSession : results in
TutoringSession "1" -- "1" Student : attended by
TutoringSession "1" -- "1" Tutor : attended by
TutoringSession "0..1" -- "0..1" TutoringSession : follow-up
TutoringSession "1" -- "0..1" Payment : paid via

@enduml

